package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class OnlineStockSpanTest {

    @Test
    public void calculateSpans_EmptyInput_ReturnsEmptyArray() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] result = solution.calculateSpans(new int[0]);
        assertTrue(java.util.Arrays.equals(result, new int[0]));
    }

    @Test
    public void calculateSpans_SingleElementInput_ReturnsCorrectSpan() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {1};
        int[] result = solution.calculateSpans(prices);
        assertEquals(1, result[0]);
    }

    @Test
    public void next_ValuesBelow100_ReturnsNextValueWithOneSpan() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int result = solution.next(60);
        assertTrue(result == 61 || result == 62);
    }

    @Test
    public void next_HigherValuesReturnCorrectPriceAndSpan() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {70, 100};
        for (int price : prices) {
            int result = solution.next(price);
            assertTrue(result == price + 1);
        }
    }

    @Test
    public void calculateSpans_MultipleValues_ReturnsCorrectSpans() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {100, 70, 60};
        int[] result = solution.calculateSpans(prices);
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(3, result[2]);
    }

    @Test
    public void calculateSpans_ValuesWithGaps_ReturnsCorrectSpans() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {100, 70, 20, 40};
        int[] result = solution.calculateSpans(prices);
        assertEquals(1, result[0]);
        assertEquals(3, result[1]);
        assertEquals(4, result[2]);
    }

    @Test
    public void calculateSpans_ValuesWithDuplicatedPrices_ReturnsCorrectSpans() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {100, 70, 100};
        int[] result = solution.calculateSpans(prices);
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(3, result[2]);
    }
}
